--
-- Table structure for table `booking`
--

DROP TABLE IF EXISTS `booking`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `booking` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `booking_no` varchar(40) NOT NULL,
  `farmer_id` bigint NOT NULL,
  `venue_id` bigint NOT NULL,
  `device_id` bigint DEFAULT NULL,
  `start_time` datetime NOT NULL,
  `end_time` datetime NOT NULL,
  `topic` varchar(120) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'pending_review',
  `review_comment` varchar(300) DEFAULT NULL,
  `recommended_time` datetime DEFAULT NULL,
  `cancel_reason` varchar(300) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `booking_no` (`booking_no`),
  KEY `idx_booking_venue_time` (`venue_id`,`start_time`),
  KEY `idx_booking_device_time` (`device_id`,`start_time`),
  KEY `idx_booking_farmer_time` (`farmer_id`,`start_time`),
  KEY `idx_booking_status` (`status`),
  CONSTRAINT `fk_booking_device` FOREIGN KEY (`device_id`) REFERENCES `device` (`id`),
  CONSTRAINT `fk_booking_farmer` FOREIGN KEY (`farmer_id`) REFERENCES `farmer` (`id`),
  CONSTRAINT `fk_booking_venue` FOREIGN KEY (`venue_id`) REFERENCES `venue` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=109 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='直播预约';
/*!40101 SET character_set_client = @saved_cs_client */;

