DROP TABLE IF EXISTS `booking_product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `booking_product` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `booking_id` bigint NOT NULL,
  `product_name` varchar(80) NOT NULL,
  `spec` varchar(80) DEFAULT NULL,
  `quantity` decimal(10,2) NOT NULL DEFAULT '0.00',
  `unit` varchar(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_booking_product_booking` (`booking_id`),
  CONSTRAINT `fk_booking_product_booking` FOREIGN KEY (`booking_id`) REFERENCES `booking` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='预约主推农产品';
/*!40101 SET character_set_client = @saved_cs_client */;

