/*!40000 ALTER TABLE `knowledge_chunk` DISABLE KEYS */;
INSERT INTO `knowledge_chunk` VALUES (4,1,0,'助农直播常见问题（系统预置）\n一、直播预约规则\n1. 谁可以提交直播预约？只有农户身份的账号可以提交直播预约，直播管理员和系统管理员不能代提。\n2. 预约时段有什么限制？直播时段按整点划分，单场时长 1 到 4 小时，不能跨天，最早提前 2 小时提交，最多提前 30 天预约。\n3. 同一场地同一时段可以预约几场直播？只允许一场，提交时系统自动校验冲突，审核通过后还会按小时锁资源兜底。\n4. 预约被驳回怎么办？审核驳回时会附上驳回原因和推荐预约时间，可以按推荐时间重新提交。\n5. 取消预约有什么限制？直播开始前 24 小时内不能再取消，取消时需要填写原因，例如农产品临时缺货。\n二、排队与候补规则\n1. 什么时候需要排队？目标时段已被其他农户预约占用时，可以加入该场地该时段的排队队列；时段空闲时直接预约即可，不需要排队。\n2. 排队号是什么格式？排队号格式为 Q-农户编号-日期-序号，例如 Q-NF2026001-20261101-001。\n3. 排队顺位怎么计算？严格按加入时间排序，前序农户取消、放弃或超时后，后面的人顺位自动前移。\n4. 候补确认有什么规则？',486,'null','2026-11-16 20:54:26'),(5,1,1,'6001-20261101-001。\n3. 排队顺位怎么计算？严格按加入时间排序，前序农户取消、放弃或超时后，后面的人顺位自动前移。\n4. 候补确认有什么规则？队首会在场地释放时升级为候补，候补需在开播前 1 小时截止时间前确认，超时自动顺延给下一位。\n5. 候补确认后又取消会怎样？确认候补生成预约后又取消的农户，72 小时内不能再加入该场地的排队队列。\n6. 排队队列会被关闭吗？直播管理员可以关闭整个场地时段的队列，关闭后队列内所有有效排队终止。\n三、通知规则\n1. 系统会发哪些通知？预约审核结果、排队顺位变化、候补确认提醒、直播开始前 1 小时提醒、设备故障预警。\n2. 通知渠道有哪些？系统内消息和短信两个渠道，设备故障等重要事件优先短信提醒。\n3. 短信发送失败怎么办？系统会按 1、5、15 分钟的间隔自动重试三次，最终失败时站内消息仍然保留，管理员也可以手动重发。\n四、设备与场地\n1. 设备编号是什么格式？设备编号格式为 ZB-场地编号-设备序号，例如 ZB-C001-01。\n2. 设备故障对预约有什么影响？',465,'null','2026-11-16 20:54:26'),(6,1,2,'以手动重发。\n四、设备与场地\n1. 设备编号是什么格式？设备编号格式为 ZB-场地编号-设备序号，例如 ZB-C001-01。\n2. 设备故障对预约有什么影响？设备报修后，系统会自动取消受影响的后续已通过预约并通知相关农户，管理员会尽快协调替代资源。\n3. 场地什么时候可以预约？场地状态为可用且在开放时段内才可以预约，可以按县域筛选查询空闲场地和设备。',177,'null','2026-11-16 20:54:26'),(7,4,0,'农产品溯源介绍：本系统对上架直播的农产品实行溯源管理。每一批主推农产品需要登记产地信息，寿县本地农产品包括草莓（采摘后48小时内冷链发货）、圣女果（当日清晨采摘分拣）、晚粳米（当季新米，真空包装）、土鸡蛋（48小时内发货）等。溯源信息包含产地县域、采收日期、储存方式与运输时效。农户在提交直播预约时，应在主推农产品清单中注明产品名称、规格和预计可售数量，便于管理员安排场地与审核。质检要求：所有上架农产品需提供质检报告或营业执照。质检报告需包含农药残留检测与糖度检测两项指标，均需合格后方可安排直播。营业执照需在有效期内，经营范围需涵盖所售农产品。资质材料上传后由直播管理员审核，状态分为待审核、已认证、未通过、停用四种。审核未通过的农户需补齐材料后重新提交。',982,NULL,'2026-11-16 23:34:56'),(8,4,1,'溯源查询与展示：直播过程中消费者可通过直播画面展示的溯源标签了解产品产地与质检信息。溯源标签由系统在预约通过后自动生成，包含农户编号、产品名称、产地县域和质检状态。销售数据录入：直播完成后，直播管理员需及时录入本场直播的销售记录，包括产品名称、规格、销售数量和单位。销售数量是统计模块的核心指标之一，用于计算农产品销量趋势和预约成功率。农户可以在我的数据页面查看自己所有已完成场次的销售统计。如发现销售记录录入有误，请联系直播管理员修改。冷链与发货：草莓、圣女果等鲜果类产品采摘后需冷藏保存，发货时效不超过48小时；大米、腊肉等耐储产品发货时效不超过72小时。发货超期可能引起消费者投诉，影响农户信誉分。',898,NULL,'2026-11-16 23:34:56'),(9,5,0,'直播设备编号规则：设备按“ZB-场地编号-设备序号”格式编号，例如 ZB-C001-01 表示一号场地的第一套设备。每套设备组合包含手机、三脚架、补光灯、无线领夹麦克风和5G路由器等配件。设备状态分为可用、维修、停用三种，只有可用状态的设备才能被预约。设备校准：每套设备都有校准周期，系统会在校准日期前7天自动向直播管理员发送校准提醒通知（系统消息和短信双渠道），逾期未校准的设备可能影响直播画质和收音质量。校准内容包括摄像头对焦检测、麦克风收音测试、补光灯亮度校准和路由器信号强度测试。校准完成后管理员需在设备管理页面更新校准日期。',763,NULL,'2026-11-16 23:34:56'),(10,5,1,'设备故障处理：直播开始前或直播过程中发现设备故障（如镜头对焦失灵、麦克风无声、补光灯不亮），直播管理员应在设备管理页面提交故障报修，填写故障部位和故障描述。报修后系统自动向受影响的农户发送设备故障通知，并自动为该时段预约推荐可用设备。故障修复后管理员提交修复说明，系统向受影响农户发送设备恢复通知。场地开放时段：直播场地有各自开放时段，预约时段必须在场地开放时段内。一号场地开放时间为08:00-20:00，二号场地为09:00-18:00。容纳人数：一号场地最多容纳20人，二号场地最多容纳15人，预约时请根据预计到场人数选择场地。',749,NULL,'2026-11-16 23:34:56'),(11,6,0,'预约提交规则：只有农户身份的账号可以提交直播预约，管理员不能代农户提交。预约需要填写所属县域、直播日期、直播时段、直播主题和主推农产品清单。直播时段按整点划分，单场时长1至4小时，不能跨天。最早可以提前2小时提交预约，最多可以提前30天预约。同一场地同一时段只允许一场直播，同一设备同一时段也只能被一场直播占用。提交时系统自动校验信息格式与资源冲突：如果目标时段场地或设备已被占用，系统会提示资源冲突并询问是否进入排队；农户同意排队后生成固定格式的排队号，格式为Q-农户ID-日期-序号。预约提交后状态为待审核，由直播管理员审核。',773,NULL,'2026-11-16 23:34:56'),(12,6,1,'审核与反馈规则：直播管理员实时接收预约申请，支持按预约时间、县域、农产品类型筛选审核列表。审核结果分通过和驳回两种，审核后系统实时通知农户。驳回时管理员需注明驳回原因，并给出推荐的预约时间。调整与取消：直播开始前12小时以上可以发起调整申请（如修改时段、更换场地设备），调整需经直播管理员人工审批后方为有效，审批结果实时同步农户。取消预约需要在直播开始前24小时以上操作，取消时必须填写取消原因（如农产品临时缺货），系统会记录取消原因。完成标记：场次结束后直播管理员可以将预约标记为已完成或未到场，已完成场次才能录入销售记录。',781,NULL,'2026-11-16 23:34:56'),(13,7,0,'排队规则：同一农户针对同一场地的同一时段只能加入一次排队队列。排队队列严格按申请时间排序，系统实时向农户展示当前排队位置和预计等待场次。当排在前面的农户取消预约时，系统实时更新后续农户的排队位置并发送顺位变化通知。当管理员释放空闲资源或前序农户取消时，系统按排队顺序触发候补通知，收到候补通知的农户需要在规定时间内选择确认预约或放弃，系统记录每次候补操作的选择结果和时间。冷却限制：候补农户确认预约后又取消的，3天内不能再加入该场地的排队队列。',664,NULL,'2026-11-16 23:34:56'),(14,7,1,'通知机制：系统基于直播流程节点自动触发五类通知：预约审核结果、排队顺位变化、候补确认提醒、直播开始前1小时提醒、设备故障预警，另有设备校准到期提醒。通知支持系统内消息和短信两种渠道，根据场景适配发送方式：设备故障预警优先短信，其余事件系统消息与短信并发。系统记录每条通知的发送状态，发送失败的通知会在规定时间内自动重新发送，确保农户能收到关键提醒。农户登录后可在通知管理页面查看全部通知和阅读状态，短信发送失败的可由直播管理员手动重试。',652,NULL,'2026-11-16 23:34:56'),(16,9,0,'版本二：规则说明版（适合 AI 助手直接调取回答）\n标题建议： 助农直播常见问题与规则解答\n正文内容：\n1. 农产品质量如何保证？\n答：所有直播售卖的农产品均需提供溯源信息与质检报告。直播间展示的实物与发货实物一致，支持坏果包赔。\n2. 预约与排队候补怎么操作？\n答：用户可在直播前通过系统进行直播预约。对于已售罄的爆款农产品，可点击“排队候补”。系统将在有库存释放时，按候补顺序通知用户付款，请留意系统消息提醒。\n3. 直播设备与画面说明：\n答：为了保证直播画面的清晰与农产品的真实色彩，直播团队会定期对摄像机、补光灯、麦克风等设备进行校准与维护，确保观众看到原汁原味的农田风貌和产品细节。\n4. 发货与物流：\n答：为了保证农产品的新鲜度，大部分生鲜类产品采用顺丰冷链或产地直发。下单后48小时内发货，偏远地区可能需要适当延长物流时间。',369,'null','2026-11-17 12:04:54');
