  KEY `idx_notification_type` (`type`),
  KEY `idx_notification_retry` (`status`,`next_retry_at`),
  KEY `idx_notification_event` (`event_key`),
  CONSTRAINT `fk_notification_account` FOREIGN KEY (`account_id`) REFERENCES `account` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=175 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='通知，按渠道分别记状态';
