INSERT INTO `notification_template` VALUES (1,'review_approved','审核通过','review','预约审核通过','${farmerName}，您预约的「${topic}」已通过审核，${startTime} 在 ${venueName} 直播，请准时到场。',1,'2026-10-20 15:12:07','2026-10-20 15:12:07'),(2,'review_rejected','审核驳回','review','预约审核未通过','${farmerName}，您预约的「${topic}」未通过审核：${reviewComment}。推荐时间：${recommendedTime}。',1,'2026-10-20 15:12:07','2026-10-20 15:12:07'),(3,'candidate_promoted','候补提醒','candidate','候补资格已获得','${farmerName}，${venueName} ${startTime} 的场次释放，您已升级为候补，请在 ${deadline} 前确认，超时自动顺延。',1,'2026-10-20 15:12:07','2026-10-20 15:12:07'),(4,'queue_position','顺位变化','queue','排队顺位更新','${farmerName}，${venueName} ${startTime} 的排队有变化，您当前顺位第 ${position} 位。',1,'2026-10-20 15:12:07','2026-10-20 15:12:07'),(5,'booking_reminder','开播提醒','reminder','开播前 1 小时提醒','${farmerName}，您预约的「${topic}」将于 ${startTime} 在 ${venueName} 开播，请提前做好准备。',1,'2026-10-20 15:12:07','2026-10-20 15:12:07'),(6,'device_fault','设备故障','device_fault','设备故障通知','${farmerName}，您 ${startTime} 在 ${venueName} 预约的设备「${deviceName}」出现故障，管理员将尽快为您调整。',1,'2026-10-20 15:12:07','2026-10-20 15:12:07'),(8,'device_recovered','设备恢复','device_fault','设备恢复通知','${farmerName}，您 ${startTime} 在 ${venueName} 预约的设备「${deviceName}」已维修完成并恢复可用。',1,'2026-11-16 18:41:07','2026-11-16 18:41:07'),(9,'adjustment_approved','调整通过','review','预约调整已通过','${farmerName}，您预约「${bookingNo}」的调整申请已通过：${startTime} 在 ${venueName} 直播，请准时到场。',1,'2026-11-16 18:41:14','2026-11-16 18:41:14'),(10,'adjustment_rejected','调整驳回','review','预约调整未通过','${farmerName}，您预约「${bookingNo}」的调整申请未通过：${reviewComment}。',1,'2026-11-16 18:41:14','2026-11-16 18:41:14'),(11,'device_fault_canceled','设备故障取消预约','device_fault','预约已因设备故障取消','${farmerName}，您 ${startTime} 在 ${venueName} 的预约「${topic}」因设备「${deviceName}」故障无法使用，已自动取消，请重新预约。',1,'2026-11-16 18:41:14','2026-11-16 18:41:14'),(12,'device_calibration','设备校准提醒','calibration','设备校准到期提醒','设备「${deviceName}」（${deviceNo}）将于 ${calibrationDate} 到达校准周期，请及时安排校准，逾期未校准设备可能影响直播质量。',1,'2026-11-16 19:07:04','2026-11-16 19:07:04');
/*!40000 ALTER TABLE `notification_template` ENABLE KEYS */;
