--
-- Table structure for table `qa_record`
--

DROP TABLE IF EXISTS `qa_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qa_record` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `account_id` bigint NOT NULL,
  `question` text NOT NULL,
  `answer` text,
  `citations` json DEFAULT NULL,
  `handoff` tinyint NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_qa_account` (`account_id`,`created_at`),
  CONSTRAINT `fk_qa_account` FOREIGN KEY (`account_id`) REFERENCES `account` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=59 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI 问答记录';
/*!40101 SET character_set_client = @saved_cs_client */;

