-- Dumping data for table `qa_record`
--

LOCK TABLES `qa_record` WRITE;
/*!40000 ALTER TABLE `qa_record` DISABLE KEYS */;
INSERT INTO `qa_record` VALUES (20,1,'你好，你能做什么','你好！我是助农直播管理系统的问答助手，主要为你解答以下咨询（只做解答，不代替操作）：\n\n**直播预约规则**\n- 预约时段：整点开始、1~4 小时、不跨天\n- 提前 2~30 天预约，仅农户身份可提交\n- 同一场地同一时段冲突校验\n\n**预约审核与调整**\n- 直播管理员审核：通过 / 驳回（注明原因并推荐时间）\n- 开播前 12 小时可申请调整，需审批\n- 取消预约需填写原因\n\n**排队候补**\n- 资源被占用时自动排队（编号 Q-农户ID-日期-序号）\n- 按申请时间排序，前序取消则顺位前移\n- 候补确认后 3 天内不能再排队\n\n**通知提醒**\n- 审核结果、顺位变化、候补确认、开播前 1 小时提醒、设备故障预警\n- 系统消息 + 短信双渠道，失败自动重试\n\n**其他业务咨询**\n- 农产品溯源与质检资料要求\n- 设备使用与校准周期\n- 数据统计指标（占用率、场次、销量、成功率）\n- 权限划分（系统管理员 / 直播管理员 / 农户主播 / 数据统计员职责）\n\n**我不能做的事**\n- 不代提交、修改或取消预约（请到对应页面操作）\n- 不查看农户完整手机号\n- 不导出数据\n\n你可以直接问我具体的规则或流程问题～','[]',0,'2026-11-17 11:03:04'),(21,5,'我要预约直播','预约直播需要您自行在系统中提交，我不能代为操作。以下是关键规则，供您提交前参考：\n\n- **身份要求**：只有农户身份的账号可以提交预约，管理员不能代提。请前往「直播预约」页面填写并提交。\n- **时段规则**：按整点划分，单场 1–4 小时，不能跨天；最早提前 2 小时、最多提前 30 天预约。\n- **场地冲突**：同一场地同一时段只允许一场直播，提交时系统自动校验；若该时段已被占用，可加入该场地时段的排队队列（排队号格式如 Q-NF2026001-20261101-001），按时段空闲则直接预约。\n- **候补提醒**：队首在场地释放时升级为候补，需在开播前 1 小时截止时间前确认，超时自动顺延给下一位；确认候补生成预约后又取消的，72 小时内不能再加入该场地队列。\n- **驳回处理**：驳回时会附驳回原因和推荐预约时间，可按推荐时间重新提交。\n- **取消限制**：开播前 24 小时内不能取消，取消需填写原因（如农产品临时缺货）。\n- **材料准备**：提交时需在主推农产品清单中注明产品名称、规格和预计可售数量；上架农产品需有质检报告（含农药残留、糖度检测且合格）或有效期内、经营范围涵盖所售农产品的营业执照。\n\n如您已准备好，请到「直播预约」页面提交；若需要我帮您梳理某一步的规则，可以继续问我。\n\n引用来源：[1][2][3]','[\"助农直播常见问题\", \"助农直播常见问题\", \"农产品溯源与质检资料\", \"农产品溯源与质检资料\"]',0,'2026-11-17 11:04:51'),(22,5,'在哪里看数据','可在系统内按以下路径查看数据：\n\n1. **登录后进入“工作台/首页”**，找到 **“数据统计”/“数据看板”** 模块。\n2. **按角色查看范围不同**：\n   - 农户主播：查看自己的直播场次、销量、预约成功率等数据。\n   - 直播管理员：查看场地占用率、直播场次、审核/开播情况等。\n   - 数据统计员：查看汇总统计指标，如占用率、场次、销量、成功率。\n   - 系统管理员：具备整体管理权限。\n3. 若看不到“数据统计”入口或数据范围不全，通常是**权限未开通**，请联系系统管理员配置。\n4. 系统仅支持查看统计，**不提供数据导出**功能。','[]',0,'2026-11-17 11:06:53'),(23,10,'你好','你好！我是助农直播管理系统助手，可以为你解答以下问题：\n\n- **直播预约规则**：时段、提前天数、身份要求、场地冲突校验\n- **预约审核与调整**：审核流程、驳回原因、开播前调整、取消规则\n- **排队候补**：排队顺序、顺位变化、候补确认限制\n- **通知提醒**：审核结果、开播提醒、故障预警等\n- **溯源质检、设备使用、数据统计、权限划分**等相关问题\n\n请直接描述你想了解的内容，我会分点为你解答。','[]',0,'2026-11-17 11:31:49'),(24,1,'用三句话介绍你能做什么','1. 我可以解答直播预约规则、预约审核与调整、取消、排队候补及通知机制等常见问题。  \n2. 我可以解答农产品溯源与质检资料、设备使用与校准周期、数据统计指标以及各类角色权限划分。  \n3. 我只提供咨询解答，不能代您提交、修改或取消预约，也不能查看完整手机号或导出数据，相关操作请到对应页面完成。','[]',0,'2026-11-17 11:33:05'),(25,1,'用三句话介绍你能做什么','我可以解答直播预约规则（如整点1~4小时、提前2~30天、同场地同时段冲突校验）以及预约的审核、调整、取消流程。我也能说明排队候补的排序与顺位规则，以及审核结果、候补确认、开播提醒、设备故障等通知渠道和重试机制。此外，我还能解答农产品溯源与质检资料、设备使用与校准周期、数据统计指标和各类角色的权限划分问题。','[]',0,'2026-11-17 11:33:06'),(26,1,'用三句话介绍你能做什么','1. 我可以解答直播预约规则（整点、1~4 小时、不跨天、提前 2~30 天、农户身份、场地时段冲突校验），以及预约审核、驳回调​​整、取消和排队候补的流程。\n2. 我可以说明通知机制（系统消息+短信、失败重试）、农产品溯源与质检资料、设备使用与校准周期、数据统计指标（占用率/场次/销量/成功率）。\n3. 我可以讲解系统管理员、直播管理员、农户主播、数据统计员的权限划分，并指引你到对应页面自行操作；但我不能代为提交、修改或取消预约，也不能查看完整手机号或导出数据。','[]',0,'2026-11-17 11:33:22'),(27,5,'你好','你好！我是助农直播管理系统助手，可以帮你解答以下问题：\n\n- **直播预约规则**：预约时段、提前天数、身份要求、场地冲突校验\n- **预约审核与调整**：审核流程、驳回原因、开播前调整、取消规则\n- **排队候补**：排队编号规则、排序方式、顺位变化、候补限制\n- **消息通知**：审核结果、顺位变化、开播提醒、设备预警\n- **溯源与质检资料**：农产品溯源信息、质检资料相关\n- **设备管理**：设备使用规范、校准周期\n- **数据统计**：占用率、场次、销量、成功率等指标\n- **权限划分**：各角色职责范围\n\n请问你想了解哪方面内容？','[]',0,'2026-11-17 11:33:38'),(28,1,'用四句话介绍你能做什么','1. 我可以解答直播预约规则，包括整点时段、1~4小时不跨天、提前2~30天、农户身份提交及同场地同时段冲突校验。  \n2. 我可以说明预约审核与调整流程，包括管理员审核通过/驳回、开播前12小时申请调整、取消需填原因等要求。  \n3. 我可以解答排队候补、系统与短信通知、农产品溯源质检、设备使用校准及数据统计指标等问题。  \n4. 我可以说明系统管理员、直播管理员、农户主播、数据统计员的权限职责；但仅做咨询解答，不能代您提交、修改或取消预约，也不能查看完整手机号或导出数据。','[]',0,'2026-11-17 11:36:32'),(29,5,'写一个冒牌排序的C++代码','知识库中未收录与该问题相关的内容，暂无法给出可靠回答。建议换个问法，或联系管理员在知识库中补充相关资料。','[]',0,'2026-11-17 11:37:43'),(30,1,'用四句话介绍你能做什么','1. 我可以解答直播预约规则，包括整点、1~4 小时、不跨天、提前 2~30 天、农户身份提交和同场地同时段冲突校验。  \n2. 我可以解答预约审核与调整、驳回原因与推荐时间、开播前 12 小时申请调整、取消填原因，以及排队候补规则和顺位变化。  \n3. 我可以解答审核结果、候补确认、开播前提醒、设备故障预警等通知机制，以及农产品溯源质检、设备校准周期和数据统计指标。  \n4. 我可以说明系统管理员、直播管理员、农户主播、数据统计员的权限划分；但不能代您提交、修改、取消预约、查看完整手机号或导出数据，相关操作请到对应页面办理。','[]',0,'2026-11-17 11:37:48'),(31,1,'用四句话介绍你能做什么','1. 我可以解答直播预约规则：整点、1~4小时、不跨天，提前2~30天，农户身份提交及同场地同时段冲突校验。  \n2. 我可以解答预约审核与调整：管理员通过/驳回及原因、推荐时间，开播前12小时申请调整，取消需填原因。  \n3. 我可以解答排队候补与通知：候补编号和排序、顺位前移、确认后3天内不能再排队，以及审核结果、提醒、故障预警等双渠道通知。  \n4. 我可以解答农产品溯源质检、设备使用校准、数据统计指标和各类角色权限；但不代您提交、修改、取消预约或导出数据。','[]',0,'2026-11-17 11:37:50'),(32,5,'你能做什么','我是助农直播管理系统的咨询助手，可以为你解答以下内容：\n\n**直播预约规则**\n- 可预约时段：整点开始，1~4 小时，不跨天\n- 需提前 2~30 天提交，仅农户身份可提交\n- 同场地同时段冲突校验规则\n\n**审核、调整与取消**\n- 直播管理员审核：通过或驳回（驳回会注明原因并推荐时间）\n- 开播前 12 小时可申请调整，需审批\n- 取消预约需填写原因\n\n**排队候补**\n- 资源被占时自动排队，编号格式为 Q-农户ID-日期-序号\n- 按申请时间排序，前序取消则顺位前移\n- 候补确认后 3 天内不能再排队\n\n**通知提醒**\n- 审核结果、顺位变化、候补确认、开播前 1 小时提醒、设备故障预警\n- 系统消息和短信两种渠道，发送失败自动重试\n\n**业务咨询**\n- 农产品溯源与质检资料要求\n- 设备使用与校准周期\n- 数据统计指标：占用率、场次、销量、成功率\n\n**权限划分**\n- 系统管理员、直播管理员、农户主播、数据统计员各自职责\n\n**我无法做的事**\n- 不能代你提交、修改或取消预约（请到对应业务页面操作）\n- 不能查看农户完整手机号\n- 不能导出数据\n\n你可以直接告诉我具体想了解的问题，我会按规则为你解答。','[]',0,'2026-11-17 11:37:55'),(33,5,'我是谁','我无法通过当前对话识别你的具体身份或账号信息。\n\n- 你可以在系统“个人中心/账号信息”页面查看自己的角色：系统管理员、直播管理员、农户主播或数据统计员。\n- 我这边不能查看你的完整手机号等敏感信息。\n- 你可以直接告诉我你的角色（如“我是农户主播”），我再按对应权限为你解答直播预约、审核、候补、通知等问题。','[]',0,'2026-11-17 11:38:10'),(34,1,'用四句话介绍你能做什么','我可以解答直播预约规则，包括整点时段、1~4小时、提前2~30天、农户身份提交及同场地同时段冲突校验。\n\n我可以说明预约审核与调整流程，包括管理员审核通过或驳回、开播前12小时申请调整需审批、取消需填原因。\n\n我可以解答排队候补机制、消息通知渠道（系统消息和短信），以及农产品溯源质检资料、设备校准周期和数据统计指标。\n\n我还可以说明各类用户权限划分；但我不代您提交、修改或取消预约，也不查看完整手机号或导出数据，操作类需求请到对应页面办理。','[]',0,'2026-11-17 11:39:05'),(35,1,'用四句话介绍你能做什么','1. 我解答直播预约规则：整点、1~4小时、不跨天、提前2~30天、农户身份及同场地同时段冲突校验。  \n2. 我解答预约审核与调整、取消原因、开播前12小时申请调整，以及排队候补顺位和3天内再排队限制。  \n3. 我解答审核结果、顺位变化、候补确认、开播前提醒、设备故障预警等系统消息与短信通知规则。  \n4. 我解答农产品溯源质检资料、设备使用与校准周期、数据统计指标及系统管理员/直播管理员/农户主播/数据统计员权限划分。','[]',0,'2026-11-17 11:40:17'),(36,1,'nihai','您好，我没太理解“nihai”的意思，您是想输入“你好”吗？\n\n我是助农直播管理系统的问答助手，可以帮您解答：\n\n- **直播预约规则**：时段（整点、1~4 小时、不跨天）、提前 2~30 天、农户身份要求、同场地同时段冲突校验\n- **预约审核与调整**：管理员通过/驳回、开播前 12 小时申请调整、取消需填原因\n- **排队候补**：编号规则、按申请时间排序、顺位前移、确认后 3 天内不能再排队\n- **通知提醒**：审核结果、顺位变化、候补确认、开播前 1 小时提醒、设备故障预警（系统消息+短信）\n- **溯源质检、设备校准、数据统计指标**\n- **各角色权限划分**\n\n请直接告诉我您想了解的具体问题，例如“预约需要提前几天？”“被驳回了怎么办？”“候补排队是怎么排的？”','[]',0,'2026-11-17 11:46:36'),(37,26,'nihao','您好！我是助农直播管理系统的问答助手，很高兴为您服务。\n\n我可以为您解答以下方面的问题：\n\n- **直播预约规则**：预约时段（整点、1~4 小时、不跨天）、提前 2~30 天、农户身份要求、场地时段冲突校验\n- **预约审核与调整**：管理员审核通过/驳回规则、开播前 12 小时申请调整、取消需填原因\n- **排队候补**：自动排队规则、排序与顺位前移、候补确认后 3 天内不可再排队\n- **通知提醒**：审核结果、顺位变化、开播前 1 小时提醒、设备故障预警（系统消息+短信双渠道）\n- **业务资料**：农产品溯源与质检资料、设备使用与校准周期、数据统计指标\n- **权限划分**：系统管理员、直播管理员、农户主播、数据统计员各自职责\n\n请注意：我只提供咨询解答，不能代您提交、修改或取消预约，也不能查看完整手机号或导出数据；相关操作请到对应页面自行完成。\n\n请问有什么可以帮您？','[]',0,'2026-11-17 11:51:01'),(38,5,'nihao','您好！我是助农直播管理系统的问答助手，可以帮您解答以下问题：\n\n- **直播预约规则**：预约时段、提前天数、场地冲突校验等\n- **审核与调整**：审核流程、驳回原因、开播前调整、取消预约\n- **排队候补**：排队规则、顺位变化、确认后限制\n- **通知提醒**：审核结果、候补通知、开播提醒、设备预警\n- **溯源与质检**：农产品溯源资料、质检资料\n- **设备管理**：设备使用、校准周期\n- **数据统计**：占用率、场次、销量、成功率等指标\n- **权限划分**：各类角色的职责范围\n\n请告诉我您想了解哪方面内容，我会为您详细解答。','[]',0,'2026-11-17 12:36:50'),(39,1,'你能做什么','我是助农直播管理系统的咨询助手，主要为农户和管理员解答规则与使用问题，具体包括：\n\n**直播预约规则**\n- 可预约时段：整点开始，时长 1~4 小时，不跨天\n- 需提前 2~30 天预约\n- 仅农户身份可提交预约\n- 同一场地、同一时段有冲突校验\n\n**预约审核与调整**\n- 直播管理员审核：通过或驳回（驳回时注明原因并推荐时间）\n- 开播前 12 小时内可申请调整，需审批\n- 取消预约需填写原因\n\n**排队候补**\n- 资源被占用时自动排队，编号格式为 Q-农户ID-日期-序号\n- 按申请时间排序，前序取消则顺位前移\n- 候补确认后 3 天内不能再排队\n\n**通知机制**\n- 审核结果、顺位变化、候补确认、开播前 1 小时提醒、设备故障预警\n- 系统消息和短信双渠道，失败自动重试\n\n**其他咨询**\n- 农产品溯源与质检资料\n- 设备使用与校准周期\n- 数据统计指标（占用率、场次、销量、成功率）\n- 权限划分（系统管理员、直播管理员、农户主播、数据统计员各自职责）\n\n**我不能做的事**：不能代您提交、修改或取消预约，不能查看农户完整手机号，不能导出数据；这类操作请到对应功能页面自行办理，遇到问题我可以告诉您该去哪一页、怎么填。','[]',0,'2026-11-17 12:38:10'),(40,5,'你好，你可以做什么','你好，我是助农直播管理系统问答助手，主要提供咨询解答，可帮你了解：\n\n- **直播预约规则**：整点/1~4小时/不跨天时段、提前2~30天、农户身份提交、同场地同时段冲突校验。\n- **预约审核与调整**：管理员审核通过/驳回、驳回原因与推荐时间、开播前12小时申请调整、取消需填原因。\n- **排队候补**：资源占用自动排队、按申请时间排序、前序取消顺位前移、候补确认后3天内不能再排队。\n- **通知机制**：审核结果、顺位变化、候补确认、开播前1小时提醒、设备故障预警，系统消息+短信双渠道及失败重试。\n- **溯源与质检**：农产品溯源资料、质检资料相关咨询。\n- **设备使用**：设备使用规范与校准周期。\n- **数据统计**：占用率、场次、销量、成功率等指标解释。\n- **权限划分**：系统管理员、直播管理员、农户主播、数据统计员各自职责。\n\n我不能代你提交/修改/取消预约、不能查看农户完整手机号、不能导出数据；操作类请求请到对应页面办理。','[]',0,'2026-11-17 12:38:23'),(41,5,'怎么预约','预约直播的规则和操作要点如下：\n\n**一、预约资格**\n- 只有农户身份的账号可以提交直播预约，直播管理员和系统管理员不能代提。\n\n**二、预约时间规则**\n- 直播时段按整点划分，单场时长 1 到 4 小时，不能跨天。\n- 最早提前 2 小时提交，最多提前 30 天预约。\n\n**三、选择场地**\n- 场地需状态为“可用”且在开放时段内。\n- 可以按县域筛选查询空闲场地和设备。\n\n**四、冲突与排队**\n- 同一场地同一时段只允许一场直播，提交时系统会自动校验冲突。\n- 如果目标时段已被占用，可以加入该场地该时段的排队队列；时段空闲则直接预约，不需要排队。\n- 排队号格式为 Q-农户编号-日期-序号，例如 Q-NF2026001-20261101-001。\n- 队首会在场地释放时升级为候补，候补需在开播前 1 小时截止时间前确认，超时自动顺延给下一位。\n\n**五、驳回与取消**\n- 预约被驳回时，会附上驳回原因和推荐预约时间，可按推荐时间重新提交。\n- 直播开始前 24 小时内不能再取消；取消时需要填写原因，例如农产品临时缺货。\n\n**操作方式**：请农户本人登录系统，在直播预约页面选择场地和时段后提交，我无法代替您提交或修改预约。\n\n引用来源：[1][2][4]','[\"助农直播常见问题\", \"助农直播常见问题\", \"助农\", \"助农直播常见问题\"]',0,'2026-11-17 12:38:38'),(42,1,'用四句话介绍你能做什么','1. 我可以解答直播预约规则，包括时段、提前天数、农户身份和场地冲突校验。  \n2. 我可以说明预约审核、驳回原因、开播前调整申请和取消原因等流程要求。  \n3. 我可以解答排队候补、通知渠道、农产品溯源质检、设备校准及数据统计指标。  \n4. 我可以说明各角色权限和操作边界，操作类请求会引导你到对应页面自行办理。','[]',0,'2026-11-17 12:49:24'),(43,1,'用四句话介绍你能做什么','1. 我可以解答直播预约规则，包括整点、1~4小时、不跨天、提前2~30天、农户身份及同场地同时段冲突校验。  \n2. 我可以说明预约审核与调整、取消规则，以及排队候补编号、排序、顺位前移和再次排队限制。  \n3. 我可以介绍审核结果、候补确认、开播提醒、设备故障等通知规则，以及溯源质检资料、设备校准周期和数据统计指标。  \n4. 我可以说明系统管理员、直播管理员、农户主播、数据统计员的权限，但不能代你提交、修改或取消预约，也不能查看完整手机号或导出数据，相关操作请到对应页面完成。','[]',0,'2026-11-17 12:50:29'),(44,1,'用四句话介绍你能做什么','1. 我可以解答直播预约规则：整点、1~4小时、不跨天，提前2~30天，农户身份要求及同场地同时段冲突校验。\n2. 我可以解答预约审核与调整：管理员通过/驳回、驳回原因与推荐时间、开播前12小时申请调整及取消需填原因。\n3. 我可以解答排队候补与通知机制：候补编号排序、顺位前移、确认后3天内限制，以及审核结果、提醒和故障预警的双渠道通知。\n4. 我可以解答农产品溯源质检、设备使用校准、数据统计指标和各类角色权限划分；操作类事项请到对应页面办理。','[]',0,'2026-11-17 12:51:44'),(45,1,'用四句话介绍你能做什么','1. 我能解答直播预约规则：整点、1～4小时、不跨天、提前2～30天、农户身份及同场地同时段冲突校验。  \n2. 我能解答审核驳回、开播前12小时调整、取消原因，以及排队候补编号、排序、顺位前移和3天限制。  \n3. 我能解答通知渠道与重试、农产品溯源质检、设备使用校准周期，以及占用率、场次、销量、成功率等统计指标。  \n4. 我能说明系统管理员、直播管理员、农户主播、数据统计员职责；但只做咨询，不代提交/修改/取消预约、不查完整手机号、不导出数据。','[]',0,'2026-11-17 12:52:26'),(46,5,'你好','你好！我是助农直播管理系统的问答助手，可以帮你解答以下方面的问题：\n\n- **直播预约规则**：预约时段、可提前天数、身份要求、同时段冲突校验\n- **预约审核与调整**：管理员审核通过/驳回、开播前申请调整、取消预约\n- **排队候补**：资源被占时自动排队、顺位排序与前移、候补确认限制\n- **消息通知**：审核结果、顺位变化、开播提醒、设备故障预警\n- **业务资料**：农产品溯源与质检、设备使用与校准周期、数据统计指标\n- **权限划分**：系统管理员、直播管理员、农户主播、数据统计员各自职责\n\n请问你想了解哪方面内容？','[]',0,'2026-11-18 13:35:59'),(47,5,'你好','你好！我是助农直播管理系统的问答助手，可以为你解答以下方面的问题：\n\n- **直播预约规则**：预约时段、提前天数、身份要求、同场地同时段冲突校验\n- **预约审核与调整**：审核通过/驳回、开播前 12 小时调整、取消原因填写\n- **排队候补**：自动排队、按申请时间排序、顺位前移、候补确认限制\n- **系统通知**：审核结果、顺位变化、开播提醒、设备故障预警\n- **溯源与质检**：农产品溯源资料、质检资料\n- **设备管理**：使用规范与校准周期\n- **数据统计**：占用率、场次、销量、成功率等指标\n- **权限划分**：系统管理员、直播管理员、农户主播、数据统计员各自职责\n\n请告诉我你想了解的具体问题～','[]',0,'2026-11-18 13:36:39'),(48,5,'不熟','您发的“不熟”信息不太完整，我不确定您想咨询哪方面。您可以告诉我具体想了解以下哪一类：\n\n1. **直播预约规则**：预约时段（整点、1~4小时、不跨天）、提前2~30天、农户身份、场地冲突校验\n2. **审核与调整**：管理员审核通过/驳回、开播前12小时申请调整、取消需填原因\n3. **排队候补**：资源被占自动排队、按申请时间排序、顺位前移、候补确认后3天内不能再排队\n4. **通知提醒**：审核结果、顺位变化、开播前1小时提醒、设备故障预警（系统消息+短信）\n5. **溯源与质检资料**、**设备使用与校准周期**\n6. **数据统计指标**：占用率、场次、销量、成功率\n7. **权限划分**：系统管理员、直播管理员、农户主播、数据统计员的职责\n\n您可以直接说“我想了解预约规则”或“排队怎么算”，我再为您详细解答。','[]',0,'2026-11-18 13:36:46'),(49,5,'ceshi','您好，感谢测试 🙂 我是助农直播管理系统的智能问答助手，可以为您解答以下方面的咨询：\n\n- **直播预约规则**：预约时段（整点起、1~4 小时、不跨天）、提前 2~30 天提交、农户身份要求、同场地同时段冲突校验\n- **预约审核与调整**：管理员审核通过/驳回（含驳回原因与推荐时间）、开播前 12 小时内可申请调整、取消需填写原因\n- **排队候补**：资源被占自动排队、按申请时间排序、前序取消后顺位前移、候补确认后 3 天内不可再排队\n- **通知提醒**：审核结果、顺位变化、候补确认、开播前 1 小时提醒、设备故障预警（系统消息 + 短信双渠道，失败自动重试）\n- **溯源与质检资料**、**设备使用与校准周期**、**数据统计指标**（占用率、场次、销量、成功率）\n- **权限划分**：系统管理员 / 直播管理员 / 农户主播 / 数据统计员各自职责\n\n请注意：我仅提供咨询解答，不代您提交、修改或取消预约，也不查看完整手机号或导出数据；操作类需求请到对应页面自助办理。\n\n有什么具体问题，直接告诉我就行～','[]',0,'2026-11-18 13:38:35'),(50,26,'nihao1','您好！我是助农直播管理系统的问答助手，很高兴为您服务。\n\n我可以帮您解答以下方面的问题：\n\n- **直播预约规则**：预约时段、提前预约天数、身份要求、场地冲突校验\n- **预约审核与调整**：审核通过/驳回、开播前12小时调整、取消原因填写\n- **排队候补**：排队编号规则、排序方式、顺位前移、候补确认限制\n- **消息通知**：审核结果、顺位变化、开播提醒、设备预警\n- **溯源与质检**：农产品溯源资料、质检资料相关\n- **设备管理**：设备使用、校准周期\n- **数据统计**：占用率、场次、销量、成功率等指标\n- **权限划分**：系统管理员、直播管理员、农户主播、数据统计员各自职责\n\n请问您想了解哪方面内容？','[]',0,'2026-11-18 14:31:00'),(51,5,'你好','你好！我是助农直播管理系统的咨询助手，可以为你解答以下问题：\n\n- **直播预约**：预约时段规则（整点、1~4 小时、不跨天）、提前 2~30 天提交、农户身份要求、同场地冲突校验\n- **审核与调整**：管理员审核通过或驳回、开播前 12 小时申请调整、取消需填原因\n- **排队候补**：候补编号规则、排序与顺位前移、确认后 3 天内不能再排队\n- **消息通知**：审核结果、顺位变化、开播提醒、设备故障预警的双渠道推送\n- **溯源与质检资料、设备使用与校准周期、数据统计指标**\n- **各类角色的权限划分**\n\n请直接描述你的疑问，我来为你解答。若是需要提交、修改、取消预约等操作，建议到对应功能页面办理哦。','[]',0,'2026-11-18 17:38:46'),(52,26,'你好','你好！我是助农直播管理系统的问答助手，可以为你解答以下问题：\n\n- **直播预约规则**：预约时段、可约日期、身份要求、冲突校验\n- **预约审核与调整**：审核通过/驳回、开播前调整、取消原因\n- **排队候补**：自动排队规则、排序与顺位前移、候补限制\n- **消息通知**：审核结果、顺位变化、开播提醒、设备预警\n- **溯源与质检**：农产品溯源资料、质检要求\n- **设备管理**：使用规范、校准周期\n- **数据统计**：占用率、场次、销量、成功率等指标\n- **权限划分**：各类角色的职责范围\n\n请告诉我你具体想了解哪方面内容。','[]',0,'2026-11-18 17:39:16'),(53,5,'你好','你好！我是助农直播管理系统问答助手，可以为你解答以下问题：\n\n- **直播预约规则**：时段、提前天数、身份要求、场地冲突校验\n- **预约审核与调整**：审核通过/驳回、开播前调整、取消原因\n- **排队候补**：排队编号、排序规则、顺位前移、候补限制\n- **通知提醒**：审核结果、顺位变化、开播提醒、设备预警\n- **溯源与质检资料**：农产品溯源、检测资料相关\n- **设备使用与校准**：设备操作、校准周期\n- **数据统计**：占用率、场次、销量、成功率等指标\n- **权限划分**：系统管理员、直播管理员、农户主播、数据统计员职责\n\n请告诉我你想了解哪方面内容。','[]',0,'2026-11-18 19:36:59'),(54,5,'nihao','您好！我是助农直播管理系统助手，可以帮您解答以下问题：\n\n- 直播预约规则（时段、提前天数、冲突校验）\n- 预约审核、调整与取消\n- 排队候补规则\n- 通知提醒机制\n- 农产品溯源与质检资料\n- 设备使用与校准周期\n- 数据统计指标\n- 各角色权限划分\n\n请问有什么可以帮您？','[]',0,'2026-11-18 20:19:08'),(55,5,'给我写个排序算法','这个问题不在我的解答范围内，抱歉——我是助农直播管理系统的问答助手，只负责解答与直播预约、审核、候补排队、通知、溯源质检、设备管理、数据统计和权限划分相关的规则问题，不提供编程代码或通用技术咨询。\n\n如果你的需求与系统有关，我可以帮你解答这类\"排序\"规则：\n\n- **排队候补顺序**：按候补申请时间先后排序，生成排队号（Q-农户ID-日期-序号），前序用户取消后顺位自动前移。\n- **预约冲突校验**：同场地、同时段（整点起 1~4 小时、不跨天）提交时如何判定冲突。\n- **数据统计口径**：场地占用率、场次数、销量、审核成功率等指标的计算方式。\n\n需要了解其中哪一项，直接告诉我即可。若你要提交预约、申请调整或取消，请到系统的\"直播预约\"页面自行操作，我这边不能代为提交或修改。','[]',0,'2026-11-18 20:19:30'),(56,5,'good','您好！我是助农直播管理系统的问答助手，很高兴为您服务。\n\n我可以为您解答以下方面的问题：\n\n- **直播预约规则**：预约时段、提前天数、身份要求、场地冲突校验\n- **预约审核与调整**：审核通过/驳回、开播前调整、取消流程\n- **排队候补**：排队规则、排序方式、顺位变化、确认限制\n- **通知提醒**：系统消息与短信渠道、提醒节点、失败重试\n- **溯源与质检**：农产品溯源资料、质检要求\n- **设备管理**：设备使用、校准周期、故障预警\n- **数据统计**：占用率、场次、销量、成功率等指标\n- **权限划分**：系统管理员、直播管理员、农户主播、数据统计员各自职责\n\n请告诉我您想了解哪方面内容，我为您详细解答。','[]',0,'2026-11-18 20:19:41'),(57,10,'你好','你好！我是助农直播管理系统问答助手，可以帮你解答以下问题：\n\n- **直播预约规则**：预约时段、提前天数、身份要求、场地冲突校验\n- **预约审核与调整**：审核通过/驳回、开播前调整、取消预约\n- **排队候补**：候补编号、排序规则、顺位前移、确认限制\n- **消息通知**：审核结果、候补提醒、开播提醒、故障预警\n- **业务资料**：农产品溯源与质检、设备使用与校准周期、数据统计指标\n- **权限划分**：系统管理员、直播管理员、农户主播、数据统计员职责\n\n请告诉我你想了解哪方面内容。','[]',0,'2026-11-19 09:41:29'),(58,10,'如何预约直播','预约直播可按以下步骤操作（需由农户账号自行在系统的直播预约页面提交，助手不能代提交）：\n\n1. **确认身份**：只有农户身份的账号可以提交直播预约，直播管理员和系统管理员不能代提。[2]\n2. **选择时段**：直播时段按整点划分，单场时长 1—4 小时，不能跨天；最早提前 2 小时提交，最多提前 30 天预约。[2]\n3. **填写预约信息**：在提交预约时，于主推农产品清单中注明产品名称、规格和预计可售数量，便于管理员安排场地与审核。[4]\n4. **提交并等待审核**：同一场地同一时段只允许一场直播，提交时系统会自动校验冲突；审核通过后还会按小时锁资源兜底。[2]\n5. **被驳回时**：审核驳回会附驳回原因和推荐预约时间，可按推荐时间重新提交。[2]\n6. **时段已被占用时**：可加入该场地该时段的排队队列；时段空闲则直接预约即可。[2] 队首会在场地释放时升级为候补，候补需在开播前 1 小时截止前确认，超时自动顺延给下一位。[3]\n7. **注意取消限制**：直播开始前 24 小时内不能再取消，取消时需填写原因。[2]\n\n引用来源：[2][4][1][3]','[\"助农\", \"助农直播常见问题\", \"助农直播常见问题\", \"农产品溯源与质检资料\"]',0,'2026-11-19 09:41:45');
