--
-- Table structure for table `queue_ticket`
--

DROP TABLE IF EXISTS `queue_ticket`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `queue_ticket` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `queue_no` varchar(50) NOT NULL,
  `farmer_id` bigint NOT NULL,
  `booking_id` bigint DEFAULT NULL,
  `venue_id` bigint NOT NULL,
  `slot_start` datetime NOT NULL,
  `slot_end` datetime NOT NULL,
  `position` int NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'queued',
  `candidate_deadline` datetime DEFAULT NULL,
  `assigned_device_id` bigint DEFAULT NULL,
  `confirmed_booking_id` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `queue_no` (`queue_no`),
  KEY `fk_queue_device` (`assigned_device_id`),
  KEY `fk_queue_booking` (`confirmed_booking_id`),
  KEY `idx_queue_venue_slot` (`venue_id`,`slot_start`,`status`),
  KEY `idx_queue_farmer_slot` (`farmer_id`,`slot_start`),
  KEY `idx_queue_booking` (`booking_id`),
  CONSTRAINT `fk_queue_booking` FOREIGN KEY (`confirmed_booking_id`) REFERENCES `booking` (`id`),
  CONSTRAINT `fk_queue_device` FOREIGN KEY (`assigned_device_id`) REFERENCES `device` (`id`),
  CONSTRAINT `fk_queue_farmer` FOREIGN KEY (`farmer_id`) REFERENCES `farmer` (`id`),
  CONSTRAINT `fk_queue_request_booking` FOREIGN KEY (`booking_id`) REFERENCES `booking` (`id`),
  CONSTRAINT `fk_queue_venue` FOREIGN KEY (`venue_id`) REFERENCES `venue` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='按场地排队';
/*!40101 SET character_set_client = @saved_cs_client */;

