DROP TABLE IF EXISTS `region`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `region` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `code` varchar(12) NOT NULL,
  `parent_code` varchar(12) DEFAULT NULL,
  `level` tinyint NOT NULL COMMENT '1省 2市 3县',
  `name` varchar(80) NOT NULL,
  `enabled` tinyint NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `idx_region_parent` (`parent_code`),
  KEY `idx_region_level` (`level`)
) ENGINE=InnoDB AUTO_INCREMENT=3948 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='行政区划字典，先导入项目区域，后续可扩全国';
