DROP TABLE IF EXISTS `venue`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `venue` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `venue_no` varchar(32) NOT NULL,
  `name` varchar(80) NOT NULL,
  `location` varchar(200) NOT NULL,
  `county_code` varchar(12) DEFAULT NULL,
  `capacity` int NOT NULL DEFAULT '0',
  `open_start` time NOT NULL,
  `open_end` time NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'available',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `venue_no` (`venue_no`),
  KEY `idx_venue_county_code` (`county_code`),
  KEY `idx_venue_status` (`status`),
  CONSTRAINT `fk_venue_region` FOREIGN KEY (`county_code`) REFERENCES `region` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='直播场地';
